"""第六组九条主要神战参与者；死亡、失能与未知不互换。"""
from audit_evidence import H,evidence,dump_group,render_characters
assert not (H/'character-arcs-part06.json').exists(), '已交审组禁止重生。'
J=[
('大圣者','1456由死亡界现身的上层威胁；明宇求它赐力，冰兰此前以生命封印的历史来自本作说明。','先夺明宇心、碎其神格化尘并食心增力→重击众神欲脱界→心的完美光明力重创，冰兰拟再以生命鲜血结界封它→拾荒者破界使其可逃，却被林纳吞消。','神力不等无条件胜，受心重创而必须逃；吞它也使林纳反噬自刺，不把强者吸收写成无代价升级。','1458明确被林纳吞消，未留其仍封冰中或独立逃活的结局；终结由多方攻守与林纳猎食形成，非陆独杀。','冰兰自承杀不了它的当时判断，与心能伤/林能吞分别有条件；研究不能把封印方案误当已实施成功，也不能把其被吞后的独立意志补写为仍活动。',[1451,1453,1455,1456,1457,1458,1459]),
('死亡剑刃·雷鸣','较早入侵中的分身/本体阶段与后期完整神级来袭分开，早退场不等最终已死。','1421第六波进攻→击毁城防、伤卡琳/蒂雅、杀斯达克，逼各盟和NPC联合→被苏菲压到残余，1430被寒刃夺神格并斩首。','玩家普通控制多MISS，但玩家伤害并非全免；双方军队真实损伤，个人强力仍受同级猎食者背袭制约。','1430本次死亡明确，施杀者寒刃；系统陆的守城奖励/MVP不是陆杀雷证明。','称号为死亡剑刃，不借用心然吟风者，也不与米迦勒的飘渺雷鸣合人；1429陆紫啸全MISS由寒刃冰盾介入，不能写为雷对玩家全伤免疫。',[631,632,633,1421,1423,1424,1425,1426,1429,1430,1434]),
('寒刃','早期城战后逃离、以旧案话语影响苏菲的敌人；旧恶证词和现场行为分层。','早次败退后再攻神隐→1430乘雷受创吞其格斩首强化→西逃遭心骨网、玩家破盾与追击→1433系统宣陆终杀并实际分装。','吸收神格不免冰盾弱点、骨网借位与多方围攻；其对苏旧案说法有私利，不能据一次敌话侦破全部往事。','1433本次死亡明确，有系统归属与物品结算；不提前到1432，也不把苏菲/陆任何一人写成全程独力杀神。','雷与寒的死亡是相继两件事；苏母火刑被后见亡体反证，寒对旧性暴力的指控仍按敌话保留，不能据其强力或死亡给全部证词盖真。',[498,499,500,981,986,987,1198,1199,1202,1429,1430,1432,1433,1434]),
('奥维亚／血指','以取心、支配与对苏菲的爱自辩，仍被苏拒绝其暴行；后有真实死而复体的新阶段。','880取云栈心→884苏斩首、系统北末杀且魂散→无头尸由心带走→986心自述救赎灵魂/用战神血液复体，现场见无头骑→护心战冰，1454被冰手刀爆上体，飞银说明神魂俱灭。','旧弃族史与爱不能抵消侵害；第一次魂散后出现特殊复体，不等所有NPC都可自动回来；神战新终死不因旧复体例外抹掉。','1454本次神魂俱灭，1495飞银仍追述其灰飞；至书末无新的复体/魂在确证，不把它写成仅失踪。','第一次斩杀、心救赎自述与当前无头实体三层相连，但复体过程未现场展示；不与仅近名的血刃等实体自动合并。',[799,880,881,884,885,886,985,986,988,1453,1454,1495]),
('飞银龙','心然的龙形坐骑/伙伴，有畏惧、自保和被驱使的阶段，本体不是骑龙的人。','885被剖小半心救云，后仍活飞助战→龙窟逃裂→为心伏寒/抗冰→被百兽老人囚驯后1495与陆同行→受箭、挡林、断翼再现，随救援跨血海→1504活返人界。','被剖/断翼是真伤，不因后活写从未伤；它会畏敌、饮血海水削夜是具体克制，不证明对一切神无敌或永远忠诚。','1504在空中探头明确活归；陆不知道它何时越裂，逃法细节未知，不编全康时间、永久阵亡或实际叛变。','与陆的上古神龙、斯特雷拉及其他龙各独立；被迫献小半心不写自愿献全心而死，陆对其不忠的怀疑不等实际叛变确证。',[882,885,983,984,989,1292,1293,1311,1432,1454,1494,1495,1496,1497,1498,1504]),
('卡兰／龙骑队长','龙域旧军人、冰兰故交，与星空剑圣卡兰斯不同；昔事多由陆转述及本人反应交代。','与明宇/米交战失臂又被切腿→1273卡琳以回魂止血保命→1452明确已加入天空城，求单战米却被雷网控、需心出手→1455劝冰同行。','重伤活不等肢体重塑/完全康复；旧仇有心介入也不当卡亲自斩米，献礼或倾慕不保证关系回应。','本书末保留活的最后明确状态，入军由1452后证补卷六阶段未知；未见与冰远走或恋情确定回应。','卡兰斯984心碎死不能算到卡兰；这里止血/仍缺肢与加入军队是不同事实，不能用后入军消掉先前真实伤。',[1246,1267,1268,1269,1273,1451,1452,1455]),
('卡兰斯／星空剑圣','天空城军中剑圣，苏菲据寒刃话指控他烧死母亲；他当场否认并说隔离亡者/烧盗。','981—983辩旧案并出战、让苏放年轻人→984仍不敌，被苏踢碎心而死→986—987苏亲见母亡体并非被烧成灰，原火刑认知受到反证。','保护年轻人的现场选择不自动证明全部旧辩词；死亡不可凭旧案新证撤销，心到场也没有救活他。','984实际死亡，书末无复活/魂归后证；其责任不能简写为火刑母亲已侦破定罪，也不能因反证火刑就宣一生清白。','卡琳对他的信任不是全知证人；母亡体能反驳烧尽说，不足独证整镇处理、寒夜细节及其全部动机。与仍活卡兰严格分人。',[981,982,983,984,986,987]),
('斯达克','人类军战士，在雷鸣来袭的真实城防战中保护卡琳与同伴。','1425—1426护战时被剑穿心，重伤仍刺雷颈；随即被雷焚灰，仅留断剑。','意志和英勇不能消除肉体毁灭，普通玩家复活/守城系统恢复比例不能无条件套其个体。','1426明确死亡；灵魂永守的遗言没有其魂实际显现或后复活的特定回执，保死亡事实与愿望分层。','不把遗言当实际幽灵现身，也不把后来军队恢复比例当已逐名恢复斯达克。',[1425,1426,1434]),
('蒂雅','早以绿龙骑士参与人界军务，后加入抗雷城防；不是冰兰、卡琳或斯达克。','雷战中1425被刺穿胸，连龙被击入坑，现场叙述明确不知存死。','重创与消失不自动等死亡；高阶龙骑同样会败，却未给其完整尸亡/复活结算。','书末仍无特定明确存死后证，终态unknown；保最后重伤与未知，不当阵亡名单确死者，也不因军队后恢复推她活。','未知是对完整后文接口匹配后的证据限制，不表示尚未执行审计；不能拿邻近斯达克被焚灰补蒂雅死。',[552,1425,1426,1434]),
]
rows=[]
for i,(name,initial,decisions,costs,terminal,boundary,ids) in enumerate(J,70):
 rows.append(dict(audit_id=f'character-arc-{i:02}',name=name,initial_comparison_stage=initial,key_decisions=decisions,costs=costs,terminal_state=terminal,evidence_boundaries=boundary,evidence=evidence(ids),review_status='draft',terminal_certainty='explicit-stage-results-plus-labelled-terminal-unknown'))
assert len(rows)==9
sha=dump_group('character-arcs-part06.json',rows,'characters','无双全书人物弧第六组9条神战参与者（待主审）')
render_characters('character-arcs-part06.md',rows,'无双全书人物弧第六组9条神战参与者（待主审）')
print(len(rows),sha)
